function u(t){if(!t)return"0 B";const e=["B","KB","MB","GB","TB","PB"];let n=t,r=0;for(;n>=1024&&r<e.length-1;)n/=1024,r++;return`${n.toFixed(1)} ${e[r]}`}function i(t){return t?`${u(t)}/s`:"0 B/s"}function a(t){if(t==null||t==="")return"-";const e=typeof t=="number"?new Date(t*1e3):new Date(t);if(isNaN(e.getTime())||e.getFullYear()<1971)return"-";const n=r=>String(r).padStart(2,"0");return`${e.getFullYear()}-${n(e.getMonth()+1)}-${n(e.getDate())} ${n(e.getHours())}:${n(e.getMinutes())}`}export{a,i as b,u as f};
